{"implementation":"def solve(case):
    segments = case['segments']
    budget = case['budget']

    sum_min = 0
    total_cap = 0
    for s in segments:
        if not all(k in s for k in ('name','importance','minimum','capacity')):
            raise ValueError('Missing required field in segment')
        sum_min += s['minimum']
        total_cap += s['capacity']

    if budget < sum_min:
        raise ValueError('Budget lower than sum of minimum quotas')
    if budget > total_cap:
        raise ValueError('Budget exceeds total capacity')

    allocations = [s['minimum'] for s in segments]
    remaining = budget - sum_min

    while remaining > 0:
        best_idx = -1
        best_ratio = -1.0
        for i, s in enumerate(segments):
            if allocations[i] < s['capacity']:
                ratio = s['importance'] / (allocations[i] + 1.0)
                if ratio > best_ratio:
                    best_ratio = ratio
                    best_idx = i
        if best_idx == -1:
            # Should never happen if budget <= total_cap
            break
        allocations[best_idx] += 1
        remaining -= 1

    by_name = {segments[i]['name']: allocations[i] for i in range(len(segments))}
    total = sum(allocations)
    return {'allocations': allocations, 'by_name': by_name, 'total': total}
"}
